[
  {
    "statement": "The most effective gear modifications for reducing unwanted fish catch in trawl fisheries include several categories of modifications.",
    "citations": []
  },
  {
    "statement": "Size-sorting escape grids fitted to trawl nets showed effectiveness in reducing unwanted fish catch.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Various grid types reduced catches of unwanted small mackerel, small monkfish, non-target whiting and haddock, small hake, unwanted spiny dogfish, non-target herring, prohibited halibut, and unwanted sizes of cod compared to trawls without grids.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Combined mesh escape panels with size-sorting grids showed strong results in reducing unwanted catch of fish, sharks and stingrays compared to standard unmodified trawl nets.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "Size-sorting escape grids with large escape openings were effective in reducing catches of unwanted fish, sharks and rays compared to standard trawl nets.",
    "citations": [
      "2726"
    ]
  },
  {
    "statement": "Square mesh codends demonstrated effectiveness in reducing unwanted catches of all monitored fish species, young individuals of commercially targeted fish, total unwanted catch, and discarded fish compared to diamond mesh codends.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Mesh escape panels or windows showed positive results in reducing unwanted catches of various fish species compared to standard diamond mesh trawl nets.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Size-sorting mesh funnels in shrimp trawls were effective in reducing catches of unwanted non-commercial or discarded fish compared to standard trawls.",
    "citations": [
      "2722"
    ]
  },
  {
    "statement": "Topless (coverless) trawls showed effectiveness in reducing the catch of unwanted Atlantic cod and discards of commercial fish species compared to conventional trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Bottom trawls with parts raised off the seabed were effective in catching fewer unwanted sharks, elasmobranchs and fish compared to conventional trawls.",
    "citations": [
      "2708"
    ]
  },
  {
    "statement": "Removing tickler chains showed effectiveness in reducing catches of non-commercial target skates, rays and sharks.",
    "citations": [
      "2709"
    ]
  },
  {
    "statement": "Removing tickler chains typically did not affect catches of commercial target species.",
    "citations": [
      "2709"
    ]
  },
  {
    "statement": "Artificial lights on fishing gear showed limited effectiveness in reducing unwanted fish catch.",
    "citations": [
      "2695"
    ]
  },
  {
    "statement": "Shrimp trawl nets with lights caught fewer unwanted fish when the lights were fitted to the fishing line compared to a conventional trawl.",
    "citations": [
      "2695"
    ]
  }
]

[
  {
    "statement": "Based on the examined studies, evidence for management interventions successfully reducing fishing effort is limited and mixed.",
    "citations": []
  },
  {
    "statement": "One study in the Pacific Ocean found that co-management systems showed no decrease in overall fishing effort in the managed area five years after implementation.",
    "citations": [
      "2910"
    ]
  },
  {
    "statement": "Territorial fishing use rights showed no decrease in overall fishing effort in the five years after implementation in the Pacific Ocean.",
    "citations": [
      "2677"
    ]
  },
  {
    "statement": "Move-on rules that establish temporary fishing restrictions when catch thresholds are reached showed promising results.",
    "citations": [
      "3815"
    ]
  },
  {
    "statement": "Two studies in the North Atlantic Ocean and North Sea found that fishing effort for cod and blue ling was reduced after the implementation of move-on rules.",
    "citations": [
      "3815"
    ]
  },
  {
    "statement": "Overall catch limits showed variable effects on fishing effort.",
    "citations": [
      "3811"
    ]
  },
  {
    "statement": "One study in the North Sea found that when annual total allowable catch limits were changed, half of the otter trawl fleet had corresponding changes in fishing effort.",
    "citations": [
      "3811"
    ]
  },
  {
    "statement": "The same study found no changes in fishing effort for the beam trawl fleet when annual total allowable catch limits were changed.",
    "citations": [
      "3811"
    ]
  },
  {
    "statement": "Many management interventions lacked direct studies evaluating the effects of those interventions on fishing effort reduction.",
    "citations": [
      "3821",
      "3817",
      "3830"
    ]
  },
  {
    "statement": "Vessel decommissioning schemes lacked direct studies evaluating their effects on fishing effort reduction.",
    "citations": [
      "3821"
    ]
  },
  {
    "statement": "Fishing permit limitations lacked direct studies evaluating their effects on fishing effort reduction.",
    "citations": [
      "3817"
    ]
  },
  {
    "statement": "Gear and vessel restrictions lacked direct studies evaluating their effects on fishing effort reduction.",
    "citations": [
      "3830"
    ]
  }
]

[
  {
    "statement": "Several actions are available to protect the reproductive success of commercially fished species.",
    "citations": []
  },
  {
    "statement": "Protecting spawning fish from capture can safeguard reproduction directly.",
    "citations": []
  },
  {
    "statement": "Studies have shown that spawning and nursery areas closed seasonally or permanently to fishing were used by tagged adult Atlantic cod for nearly a third of the time during spawning.",
    "citations": [
      "2938"
    ]
  },
  {
    "statement": "Setting a minimum landing size for commercially fished species can protect immature fish before the fish have the opportunity to reproduce.",
    "citations": []
  },
  {
    "statement": "A global review found that only one of five swordfish fisheries showed increased recruitment after setting recommended minimum landing sizes.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "One study reported that most fish in commercial catches were still immature despite established minimum sizes.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "Temporal restrictions include establishing temporary fishery closures.",
    "citations": []
  },
  {
    "statement": "Tagged adult cod spent nearly a third of their time inside a seasonally closed spawning area, which provided increased protection during the spawning period.",
    "citations": [
      "2664"
    ]
  },
  {
    "statement": "Long-term fishery closures can protect fish populations.",
    "citations": []
  },
  {
    "statement": "Studies showed a higher abundance of young salmon and improved weights of young salmon returning to rivers in the five years after the closure of a commercial coastal fishery.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Establishing territorial user rights for fisheries demonstrated benefits for reproductive success.",
    "citations": []
  },
  {
    "statement": "One study found larger-sized and more numerous egg capsules, and more larvae of Chilean abalone up to 21 months after establishing fishing restrictions compared to open-access areas.",
    "citations": [
      "2104"
    ]
  },
  {
    "statement": "Gear modifications can reduce the capture of juvenile fish before the fish reach reproductive maturity.",
    "citations": []
  },
  {
    "statement": "Using larger mesh sizes in fishing nets improved size-selectivity and reduced catches of unwanted small or undersized fish in 15 of 20 studies across multiple marine regions.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Using larger mesh sizes in fishing nets allows juvenile fish to escape and reach reproductive age.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Marine Protected Areas that prohibit commercial fishing can protect both spawning grounds and nursery areas.",
    "citations": [
      "2225"
    ]
  },
  {
    "statement": "The effectiveness of Marine Protected Areas varies by species and implementation.",
    "citations": [
      "2225"
    ]
  }
]

[
  {
    "statement": "Prohibiting spearfishing in marine reserves in the Mediterranean provides several conservation benefits for fish populations.",
    "citations": []
  },
  {
    "statement": "Prohibiting spearfishing and line fishing in protected areas in the Mediterranean Sea increased the abundances of European seabass and gilthead seabream compared to fished areas after two to seven years.",
    "citations": [
      "2672"
    ]
  },
  {
    "statement": "European seabass were larger in size in Mediterranean areas where spearfishing was prohibited compared to fished areas after two to seven years.",
    "citations": [
      "2672"
    ]
  },
  {
    "statement": "Prohibiting spearfishing in specific zones of a Mediterranean marine reserve resulted in higher commercial and recreational fishery catches of targeted common dentex compared to zones that allowed spearfishing after one to three years.",
    "citations": [
      "2672"
    ]
  },
  {
    "statement": "Marine protected areas in the Mediterranean Sea prohibiting all types of fishing for between three and 16 years had different fish community composition compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Mediterranean marine protected areas that had prohibited all fishing for between one to more than 25 years had higher fish species richness compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Mediterranean marine protected areas that prohibited all fishing for up to 25 years had higher abundances and biomasses of all fish compared to unprotected fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Fishery targeted fish species had higher abundances and biomasses in Mediterranean marine protected areas that prohibited all fishing for up to 25 years compared to unprotected fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Fish in non-fished Mediterranean marine reserves were found to be larger overall compared to fished areas after one to 22 years.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Non-fished Mediterranean marine reserves had larger individuals of monitored fish species compared to fished areas after one to 22 years.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "More eggs of four commercially targeted fish species were found inside a non-fished Mediterranean marine reserve enforced for three years than in fished areas outside the reserve.",
    "citations": [
      "2682"
    ]
  }
]

[
  {
    "statement": "Studies examining the prohibition of different types of bottom fishing gear show varied effects on marine fish populations.",
    "citations": []
  },
  {
    "statement": "Prohibiting all mobile and static fishing gears that catch bottom species showed mixed results.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "One study found that prohibiting all mobile and static fishing gears led to higher numbers of larger and older cod after 15 years.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "Another study found no effect on fish densities after 2-7 years of prohibiting all mobile and static fishing gears.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "Cod showed better growth in areas closed to fishing for 5-15 years compared to openly fished areas.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "Prohibiting mobile fishing gears dragged across the seafloor, also known as bottom trawling, had variable effects on fish abundance across studies.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Two studies found that prohibiting bottom trawling resulted in increased total fish biomass after 15 years.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Some studies found a higher biomass of adult red mullet after 14 years of prohibiting bottom trawling.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Two other studies found no effect on bottom-dwelling fish abundance after 5 and 10 years of prohibiting bottom trawling.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Red mullet recruitment increased after 14 years of closing an area to bottom trawling.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Haddock recruitment showed no improvement after an area was closed to bottom trawling for 7 years.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Fish size responses to prohibiting bottom trawling varied.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Adult red mullet were larger 14 years after an area was closed to bottom trawling.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "The overall effects of prohibiting bottom trawling on fish size were mixed across studies and varied by fish group and habitat type.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Prohibiting shellfish dredging specifically showed no effect on bottom-dwelling fish species richness or abundance after 10 years in one North Sea study.",
    "citations": [
      "2668"
    ]
  },
  {
    "statement": "The use of semi-pelagic trawl instead of bottom trawl reduced commercial fish catch abundance compared to demersal trawling.",
    "citations": [
      "2118"
    ]
  },
  {
    "statement": "Areas allowing only hook and line fishing showed greater increases in lobster abundance over 4 years compared to fully fished sites.",
    "citations": [
      "2233"
    ]
  },
  {
    "statement": "Areas allowing only hook and line fishing showed greater increases in lobster size over 4 years compared to fully fished sites.",
    "citations": [
      "2233"
    ]
  }
]

[
  {
    "statement": "Several alternatives to setting catch quotas exist for controlling fishing mortality.",
    "citations": []
  },
  {
    "statement": "Effort controls include limiting the number of fishing days.",
    "citations": [
      "3804"
    ]
  },
  {
    "statement": "Limiting the number of fishing days resulted in higher biomass of thornback and brown rays in the Mediterranean Sea following a decrease in the overall number of days fished by a bottom trawl fleet.",
    "citations": [
      "3804"
    ]
  },
  {
    "statement": "Vessel restrictions can limit fishing activity by vessel size and/or engine power.",
    "citations": [
      "3809"
    ]
  },
  {
    "statement": "In the North Sea, excluding vessels with higher engine power from an area for half of each year resulted in a higher abundance of commercially targeted fish.",
    "citations": [
      "3809"
    ]
  },
  {
    "statement": "Licensing systems can limit the number of fishing permits or licences to limit vessel or fisher numbers.",
    "citations": [
      "3817"
    ]
  },
  {
    "statement": "No studies were found evaluating the use of licensing systems to limit vessel or fisher numbers.",
    "citations": [
      "3817"
    ]
  },
  {
    "statement": "Technical measures for controlling fishing mortality include prohibiting certain gear types.",
    "citations": [
      "3810"
    ]
  },
  {
    "statement": "Prohibiting certain gear types showed higher fish density in areas where all but one gear type was prohibited compared to areas with fewer restrictions or unrestricted areas.",
    "citations": [
      "3810"
    ]
  },
  {
    "statement": "Using larger mesh sizes can reduce unwanted catch and improve size-selectivity.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Studies showed that using larger mesh sizes reduced catches of unwanted fish in most cases.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Using larger mesh sizes improved size-selectivity for all fish species assessed.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Limiting or prohibiting specific fishing methods has been implemented as a control on fishing mortality.",
    "citations": [
      "3546"
    ]
  },
  {
    "statement": "Limited evidence exists on the effectiveness of limiting or prohibiting specific fishing methods.",
    "citations": [
      "3546"
    ]
  },
  {
    "statement": "Spatial and temporal restrictions include establishing temporary fishery closures and long-term fishery closures.",
    "citations": [
      "3545",
      "2655"
    ]
  },
  {
    "statement": "Long-term fishery closures showed varied results, including higher abundance of some fish species in closed areas.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Long-term fishery closures also showed a reduced flight response distance in fish in closed areas.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Move-on rules, which establish temporary fishing restrictions when catch thresholds are reached, have reduced cod discards and fishing effort.",
    "citations": [
      "3815"
    ]
  },
  {
    "statement": "Rights-based management alternatives include catch shares systems.",
    "citations": []
  },
  {
    "statement": "Fisheries managed under catch shares were more likely to meet biomass sustainability targets compared to non-catch share fisheries.",
    "citations": [
      "3812"
    ]
  },
  {
    "statement": "Fisheries managed under catch shares had lower rates of over-exploitation compared to non-catch share fisheries.",
    "citations": [
      "3812"
    ]
  },
  {
    "statement": "Setting catch shares by species reduced unwanted halibut catch in a multi-species fishery compared to previous systems.",
    "citations": [
      "3814"
    ]
  }
]

[
  {
    "statement": "Different fishing practices significantly affect fish survival after capture and release.",
    "citations": []
  },
  {
    "statement": "Hook and line fishing provides greater fish vitality, which is an indicator of post-release survival, compared to other gear types.",
    "citations": [
      "2732"
    ]
  },
  {
    "statement": "Fish survival rates vary considerably by species and capture conditions.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Studies have shown that 76-92% of unwanted small-spotted catshark, thorny skate, pearl perch, and Atlantic wolffish survived for 1 hour to 5 days after capture and release.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Less than half of smooth skate survived after capture and release.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Nearly all yelloweye rockfish survived for four days after capture and release.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Canary rockfish survival decreased with increasing capture depth.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "The type of hook used for fishing affects survival outcomes.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "Using different hook types in longline or recreational fisheries reduced fish hook injuries that are associated with higher post-release mortality.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "The use of different hook types reduced capture mortality of some unwanted shark and ray species compared to conventional hooks.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "Other studies found no reduction in post-release mortality for certain species like young sea breams when using different hook types.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "Circle hooks specifically show mixed effects on survival.",
    "citations": [
      "3559"
    ]
  },
  {
    "statement": "Two studies found similar survival rates for sea turtles caught by circle hooks versus J-hooks.",
    "citations": [
      "3559"
    ]
  },
  {
    "statement": "One review found fewer sea turtle deaths when circle hooks were used in four of five fisheries.",
    "citations": [
      "3559"
    ]
  },
  {
    "statement": "Fish survival is negatively affected by injuries from hooking and capture depth.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Longer tow durations negatively affect fish survival.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Modifications to longline configurations also impact survival.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "For two of three species studied, nylon hook attachment lines showed higher survival for unwanted sharks and rays compared to wire.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "One study found reduced survival for a species when using nylon hook lines.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "According to one global systematic review, using different bait types did not increase the survival of sharks and rays on gear retrieval.",
    "citations": [
      "2700"
    ]
  }
]

[
  {
    "statement": "The effects of prohibiting all commercial fishing on fish abundance show considerable variation across different ocean basins.",
    "citations": [
      "2667",
      "2682"
    ]
  },
  {
    "statement": "In the Tasman Sea, studies found mixed results, with most fish species in an estuary showing lower abundance two years after a commercial fishing closure.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "A separate study in the Tasman Sea found that fish abundance varied over 10 years and was higher for some groups compared to areas open to fishing.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the Indian Ocean, areas banning all commercial fishing for five years showed higher abundances of three of twelve commercially targeted and non-targeted fish species compared to unprotected fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the Indian Ocean, the overall size of fish was bigger in areas that banned all commercial fishing for five years.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the Mediterranean Sea, studies showed no increase in white seabream and gilthead bream biomass 2-13 years after a fishing closure compared to unprotected fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the South Atlantic Ocean, a reserve closed to all commercial fishing for 40 years showed higher abundances of five of five commercially exploited species.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "The same reserve in the South Atlantic Ocean that was closed for 40 years showed no change in species composition compared to fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "The Gulf of Mexico showed higher abundances of one of four commercially targeted fish species in protected areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the South China Sea, the overall fish density in the wider region increased in the five years after the creation of marine reserves with commercial fishing limits.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "More comprehensive studies across multiple ocean basins found that marine protected areas prohibiting all fishing for up to 25 years or more generally had higher fish abundances.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "The effects of fishing prohibitions on fish abundance varied between fish species, food chain position, commercial target status, fish sizes, depth, and habitat types.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Studies spanning numerous ocean basins found that 30 of 54 studies showed higher fish abundances in protected areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Out of 54 studies spanning numerous ocean basins, 8 showed similar fish abundances in protected and unprotected areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Out of 54 studies spanning numerous ocean basins, 16 showed mixed effects on fish abundance depending on species characteristics.",
    "citations": [
      "2682"
    ]
  }
]

[
  {
    "statement": "Several non-gear-modification strategies have been evaluated for reducing unwanted fish catch.",
    "citations": []
  },
  {
    "statement": "Establishing move-on rules for temporary, targeted fishing restrictions or closures when a catch threshold is reached has shown effectiveness.",
    "citations": [
      "3815"
    ]
  },
  {
    "statement": "One study found lower overall cod discards after the implementation of move-on rules.",
    "citations": [
      "3815"
    ]
  },
  {
    "statement": "Setting catch limits or quotas for non-targeted commercial catch was found to reduce unwanted catch in two of three cases according to a review.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "One study found that catch limits for non-target commercial species reduced the amount of unwanted halibut.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "Temporary fishery closures demonstrated benefits for turtle populations.",
    "citations": [
      "3545"
    ]
  },
  {
    "statement": "One study found fewer lethal strandings of loggerhead and Kemp's ridley turtles during seasonal shrimp trawling closures.",
    "citations": [
      "3545"
    ]
  },
  {
    "statement": "Technology to communicate near real-time catch information to fishers showed promise, with reductions of unwanted catch or discards reported in two of three cases.",
    "citations": [
      "3826"
    ]
  },
  {
    "statement": "Prohibiting high grading, which is landing only the most profitable individuals or species, did not eliminate the discarding of legal-sized but unwanted fish in one study.",
    "citations": [
      "3823"
    ]
  },
  {
    "statement": "No studies were found that directly evaluated the effects of human observers onboard fishing vessels on reducing unwanted catch.",
    "citations": []
  },
  {
    "statement": "No studies were found that directly evaluated the effects of vessel monitoring systems on reducing unwanted catch.",
    "citations": []
  },
  {
    "statement": "No studies were found that directly evaluated the effects of promoting seafood certification on reducing unwanted catch.",
    "citations": []
  },
  {
    "statement": "No studies were found that directly evaluated the effects of legislating mandatory landing of all quota species catch on reducing unwanted catch.",
    "citations": []
  }
]

[
  {
    "statement": "Several management actions are available to specifically protect the reproductive capacity of fish populations.",
    "citations": []
  },
  {
    "statement": "Protecting spawning fish from capture is a direct management approach.",
    "citations": [
      "2938"
    ]
  },
  {
    "statement": "Protecting spawning fish involves seasonal fishery closures to protect spawning individuals.",
    "citations": [
      "2938"
    ]
  },
  {
    "statement": "Studies have shown that spawning areas closed seasonally or permanently to fishing were used by tagged adult Atlantic cod for nearly a third of the time during spawning.",
    "citations": [
      "2938"
    ]
  },
  {
    "statement": "Releasing males of species known to guard nests during the breeding season is a targeted approach.",
    "citations": [
      "2734"
    ]
  },
  {
    "statement": "No studies have yet evaluated the effects on marine fish populations of releasing males of species known to guard nests.",
    "citations": [
      "2734"
    ]
  },
  {
    "statement": "Establishing temporary fishery closures provides broader protection for fish populations.",
    "citations": [
      "2664"
    ]
